 static readonly List<Field> fields=new();static readonly Dictionary<string,string> drafts=new();static readonly HashSet<string> enabled=new();static readonly Dictionary<IntPtr,Owned> owned=new();static readonly Dictionary<IntPtr,ModCopy> modCopies=new();static readonly Dictionary<IntPtr,Shared> shared=new();
 static readonly EquipmentSlot[] slots={EquipmentSlot.FirstPrimaryWeapon,EquipmentSlot.SecondPrimaryWeapon,EquipmentSlot.Holster};static readonly string[] names={"第一主武器","第二主武器","手枪","浏览武器模板","参数预设"};
 static readonly string[] basic={"RecoilForceUp","RecoilForceBack","RecoilCamera","RecoilReturnSpeedHandRotation","RecoilDampingHandRotation","Ergonomics","bFirerate","SingleFireRate","CenterOfImpact","ShotgunDispersion","Velocity","Weight","Durability","MaxDurability","HeatFactorGun","CoolFactorGun","HeatFactorByShot"};
