 static readonly List<WeaponTuningPreset> presets=new();static readonly List<(string Id,string Name)> templates=new();static readonly HashSet<string> weaponParents=new(){"5422acb9af1c889c16000029"},none=new();
 static LiveActorReference? aiActor;static EquipmentSlot aiSlot;
 internal static bool AiOpen=>aiActor!=null;
 internal static void CloseAi(){aiActor=null;selected=null;selectedId="";}
 internal static void OpenAi(GameWorld world,Player actor,EquipmentSlot slot){aiActor=new(world,actor);aiSlot=slot;tab=Array.IndexOf(slots,slot);if(tab<0)throw new ArgumentException("该槽位不是枪械槽。");editTab=tab;scopeTemplate=false;var gun=actor.Profile?.Inventory?.Equipment?.GetSlot(slot)?.ContainedItem?.TryCast<Weapon>()??throw new ArgumentException("该槽位没有枪械。");Read(gun);}
 static Player? PreviewOwner(){try{return aiActor?.Resolve()??Singleton<GameWorld>.Instance?.MainPlayer;}catch{return null;}}
 static Player Owner()=>aiActor?.Resolve()??Singleton<GameWorld>.Instance?.MainPlayer??throw new ArgumentException("角色暂不可用。");
 static int tab,editTab;static bool scopeTemplate,ignoreAttachments,loaded,corrupt;static Weapon? selected;static IntPtr worldPointer,factoryPointer;static string selectedId="",notice="",query="",lastQuery="\0",presetName="",presetId="",durability="100",maxDurability="100";static Vector2 scroll,templateScroll,presetScroll;static float nextTick;static string readback="";
 static string FilePath=>Path.Combine(BepInEx.Paths.PluginPath,"LocalSpt5ESP","weapon-tuning-presets.json");
 static PropertyInfo Property(object target,string name)=>target.GetType().GetProperty(name,BindingFlags.Public|BindingFlags.Instance)??throw new ArgumentException("该参数暂不支持："+name);
 static (object Owner,PropertyInfo Property) Resolve(WeaponTemplate template,string path){object current=template;var parts=path.Split('.');for(int i=0;i<parts.Length-1;i++)current=Property(current,parts[i]).GetValue(current)??throw new ArgumentException("该型号没有 "+parts[i]);return(current,Property(current,parts[^1]));}
 static double Get(WeaponTemplate template,Field field){var item=Resolve(template,field.Path);return Convert.ToDouble(item.Property.GetValue(item.Owner),CultureInfo.InvariantCulture);}
 static void Set(WeaponTemplate template,Field field,double value){var item=Resolve(template,field.Path);item.Property.SetValue(item.Owner,field.Integer?(object)checked((int)value):(float)value);}
 static object CloneNative(Il2CppSystem.Object source){var clone=source.MemberwiseClone();return Activator.CreateInstance(source.GetType(),clone.Pointer)??throw new InvalidOperationException("无法准备这件装备的修改。");}
 static WeaponTemplate Clone(WeaponTemplate source){var clone=(WeaponTemplate)CloneNative(source);if(clone.Pointer==source.Pointer)throw new InvalidOperationException("这件装备暂不可编辑。");foreach(string name in new[]{"WeaponRecoilSettings","WeaponAimSettings"}){var property=Property(source,name);if(property.GetValue(source) is Il2CppSystem.Object nested)property.SetValue(clone,CloneNative(nested));}return clone;}
 internal static void CheckNativeClone(Weapon gun){var template=gun.Template;float original=template.Ergonomics;var clone=Clone(template);clone.Ergonomics=original==1?2:1;if(template.Ergonomics!=original||clone.Ergonomics==original)throw new InvalidOperationException("原生武器模板未隔离。");foreach(var mod in gun.Mods){var source=mod.Template;float recoil=source.Recoil;var copy=(ModTemplate)CloneNative(source);copy.Recoil=recoil==1?2:1;if(source.Recoil!=recoil)throw new InvalidOperationException("原生配件模板未隔离。");break;}Plugin.Self.Log.LogInfo("Weapon editor native template clone check passed: weapon/nested settings/mod templates isolated; source preset unchanged");}
 static void Define(WeaponTemplate template){fields.Clear();foreach(string key in basic){var property=template.GetType().GetProperty(key);if(property?.CanRead!=true||property.CanWrite!=true||property.PropertyType!=typeof(float)&&property.PropertyType!=typeof(int))continue;double min=key=="Velocity"?-100:key is "bFirerate" or "SingleFireRate"?1:0;fields.Add(new(key,labels.GetValueOrDefault(key,key),property.PropertyType==typeof(int),min));}foreach(string section in new[]{"WeaponRecoilSettings","WeaponAimSettings"})if(Property(template,section).GetValue(template) is object nested)foreach(var property in nested.GetType().GetProperties(BindingFlags.Public|BindingFlags.Instance).Where(p=>p.CanRead&&p.CanWrite&&(p.PropertyType==typeof(float)||p.PropertyType==typeof(int))))fields.Add(new(section+"."+property.Name,(section=="WeaponRecoilSettings"?"后座 / ":"瞄准 / ")+property.Name,property.PropertyType==typeof(int),double.NegativeInfinity));}
 static void Read(Weapon gun){selected=gun;selectedId=gun.Id;worldPointer=Comfort.Common.Singleton<GameWorld>.Instance?.Pointer??IntPtr.Zero;factoryPointer=Singleton<ItemFactory>.Instance?.Pointer??IntPtr.Zero;Define(gun.Template);drafts.Clear();enabled.Clear();foreach(var field in fields)drafts[field.Path]=Get(gun.Template,field).ToString("G9",CultureInfo.InvariantCulture);ignoreAttachments=owned.TryGetValue(gun.Pointer,out var state)&&state.Ignore;durability=(gun.Repairable?.Durability??0).ToString("G9",CultureInfo.InvariantCulture);maxDurability=(gun.Repairable?.MaxDurability??0).ToString("G9",CultureInfo.InvariantCulture);scroll=Vector2.zero;readback=Final(gun);}
 static Weapon Require(){var world=Singleton<GameWorld>.Instance;var player=Owner();if(!RaidClock.Active||world?.Pointer!=worldPointer||Singleton<ItemFactory>.Instance?.Pointer!=factoryPointer||selected==null||selected.Id!=selectedId||player.HealthController?.IsAlive!=true)throw new ArgumentException("角色或武器已改变，请重新读取。");if(tab<3){var actual=player.Profile?.Inventory?.Equipment?.GetSlot(aiActor!=null?aiSlot:slots[tab])?.ContainedItem;if(actual?.Pointer!=selected.Pointer)throw new ArgumentException("该武器已离开原装备槽，请重新读取。");}return selected;}
 static Dictionary<string,double> Values(){var result=new Dictionary<string,double>();foreach(var field in fields)if(enabled.Contains(field.Path))result[field.Path]=WeaponEditorRules.Number(drafts[field.Path],field.Integer,field.Minimum);return result;}
 static void RestoreMods(IntPtr owner){foreach(var key in modCopies.Where(pair=>pair.Value.Owner==owner).Select(pair=>pair.Key).ToArray()){var copy=modCopies[key];try{if(copy.Mod?.Template?.Pointer==copy.Copy.Pointer)copy.Mod._Template_k__BackingField=copy.Original;}finally{modCopies.Remove(key);}}}
 static void IgnoreMods(Owned state){var seen=new HashSet<IntPtr>();foreach(var mod in state.Gun.Mods){if(mod==null)continue;seen.Add(mod.Pointer);if(modCopies.ContainsKey(mod.Pointer))continue;var original=mod.Template;var clone=(ModTemplate)CloneNative(original);clone.Recoil=0;clone.Ergonomics=0;clone.Accuracy=0;clone.Velocity=0;mod._Template_k__BackingField=clone;modCopies[mod.Pointer]=new(mod,original,clone,state.Gun.Pointer);}foreach(var key in modCopies.Where(pair=>pair.Value.Owner==state.Gun.Pointer&&!seen.Contains(pair.Key)).Select(pair=>pair.Key).ToArray()){var copy=modCopies[key];if(copy.Mod?.Template?.Pointer==copy.Copy.Pointer)copy.Mod._Template_k__BackingField=copy.Original;modCopies.Remove(key);}state.Gun._lastModsCalculateFrame=-1;}
 static void Refresh(Weapon gun){gun._lastModsCalculateFrame=-1;gun.RaiseRefreshEvent(true,true);var player=owned.TryGetValue(gun.Pointer,out var entry)?entry.Owner.Resolve():Owner();if(player?.HandsController?.TryCast<Player.FirearmController>()?.Item?.Pointer==gun.Pointer)player.ProceduralWeaponAnimation?.UpdateWeaponVariables();player?.Physical?.MarkWeightAsDirty();readback=Final(gun);}
 static string Final(Weapon gun)=>$"当前数值：工效 {gun.ErgonomicsTotal:G6} · 后座 {gun.RecoilTotal:G6} · 散布 {gun.GetTotalCenterOfImpact(true):G6} · 初速 {gun.TotalVelocity:G6} · 射速 {gun.FireRate}";
 static void Apply(){var gun=Require();var values=Values();var fieldsNow=fields.ToDictionary(field=>field.Path);WeaponTemplate template;if(aiActor!=null)scopeTemplate=false;if(scopeTemplate||tab==3){if(owned.TryGetValue(gun.Pointer,out var previous)){RestoreMods(gun.Pointer);gun._Template_k__BackingField=previous.Original;owned.Remove(gun.Pointer);}template=gun.Template;if(!shared.ContainsKey(template.Pointer))shared[template.Pointer]=new(template,Clone(template));}else{if(!owned.TryGetValue(gun.Pointer,out var current)){current=new Owned{Gun=gun,Owner=new LiveActorReference(Singleton<GameWorld>.Instance,Owner()),Original=gun.Template,Clone=Clone(gun.Template)};owned[gun.Pointer]=current;gun._Template_k__BackingField=current.Clone;}template=current.Clone;}
  var backup=Clone(template);try{foreach(var pair in values)Set(template,fieldsNow[pair.Key],pair.Value);foreach(var pair in values){double wanted=fieldsNow[pair.Key].Integer?pair.Value:(float)pair.Value;if(Get(template,fieldsNow[pair.Key])!=wanted)throw new InvalidOperationException("参数未能生效："+fieldsNow[pair.Key].Name);}if(owned.TryGetValue(gun.Pointer,out var state)){state.Ignore=ignoreAttachments;if(state.Ignore)IgnoreMods(state);else RestoreMods(gun.Pointer);}else if(ignoreAttachments)notice="模板参数已写入；忽略配件仅可应用于当前这把枪。";Refresh(gun);notice=(scopeTemplate||tab==3?"本战局同型号模板":"当前这把枪")+"已应用。";FeatureToasts.Show("枪械数值已应用");}catch{foreach(var field in fieldsNow.Values)Set(template,field,Get(backup,field));throw;}}
 static void RestoreSelected(){var gun=Require();if(owned.Remove(gun.Pointer,out var state)){RestoreMods(gun.Pointer);if(gun.Template.Pointer==state.Clone.Pointer)gun._Template_k__BackingField=state.Original;}if((scopeTemplate||tab==3)&&shared.Remove(gun.Template.Pointer,out var common)){Define(common.Template);foreach(var field in fields)Set(common.Template,field,Get(common.Original,field));}Refresh(gun);Read(gun);notice="已恢复所选作用范围的原值。";}
 static void Condition(){var gun=Require();var values=WeaponConditionRules.Parse(durability,maxDurability);var repair=gun.Repairable??throw new ArgumentException("该武器没有耐久组件。");repair.MaxDurability=values.Maximum;repair.Durability=values.Current;Refresh(gun);notice=$"耐久 {repair.Durability:G9} / {repair.MaxDurability:G9}";}
 static void Load(){if(loaded)return;loaded=true;try{presets.AddRange(PresetStorage.Load<WeaponTuningPreset>(FilePath));}catch(Exception e){corrupt=true;notice="方案文件读取失败，原文件保留："+e.Message;}}
 static void Save(bool copy){if(corrupt)throw new ArgumentException("请先修复参数方案文件。");string name=WeaponEditorRules.PresetName(presetName);var values=Values();if(values.Count==0)throw new ArgumentException("请至少勾选一个要保存的参数。");var preset=new WeaponTuningPreset{Id=copy||presetId.Length==0?Guid.NewGuid().ToString("N"):presetId,Name=name,Template=selected?.StringTemplateId??"",IgnoreAttachments=ignoreAttachments,Values=values};var next=presets.Where(p=>p.Id!=preset.Id).Append(preset).ToList();PresetStorage.Save(FilePath,next);presets.Clear();presets.AddRange(next);presetId=preset.Id;notice=copy?"已另存为："+name:"已保存："+name;}
 static void Use(WeaponTuningPreset preset){if(selected==null)throw new ArgumentException("先在装备槽或武器模板中选中一把枪。");enabled.Clear();foreach(var pair in preset.Values)if(fields.Any(field=>field.Path==pair.Key)){enabled.Add(pair.Key);drafts[pair.Key]=pair.Value.ToString("G9",CultureInfo.InvariantCulture);}ignoreAttachments=preset.IgnoreAttachments;presetId=preset.Id;presetName=preset.Name;tab=editTab;notice="已载入参数草稿，点击应用后生效。";}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;Plugin.Self.Log.LogWarning("Weapon editor: "+e.Message);}}
 internal static void Tick(GameWorld? world,Player? player){if(world==null||player==null){if(worldPointer!=IntPtr.Zero||aiActor!=null||owned.Count>0||shared.Count>0)Reset();return;}if(worldPointer!=IntPtr.Zero&&world.Pointer!=worldPointer){Reset();return;}if(aiActor!=null)try{aiActor.Resolve();}catch{CloseAi();}if(owned.Count==0&&shared.Count==0)return;if(Time.unscaledTime<nextTick)return;nextTick=Time.unscaledTime+.5f;foreach(var state in owned.Values.ToArray())try{var owner=state.Owner.Resolve();bool equipped=false;foreach(var slot in slots)if(owner.Profile?.Inventory?.Equipment?.GetSlot(slot)?.ContainedItem?.Pointer==state.Gun.Pointer){equipped=true;break;}if(!equipped){RestoreMods(state.Gun.Pointer);if(state.Gun.Template?.Pointer==state.Clone.Pointer)state.Gun._Template_k__BackingField=state.Original;owned.Remove(state.Gun.Pointer);continue;}if(state.Ignore)IgnoreMods(state);}catch(Exception e){notice=e.Message;try{RestoreMods(state.Gun.Pointer);if(state.Gun.Template?.Pointer==state.Clone.Pointer)state.Gun._Template_k__BackingField=state.Original;}catch{}owned.Remove(state.Gun.Pointer);}}
 internal static void ForgetRemoved(Item item){if(owned.Remove(item.Pointer,out var state)){RestoreMods(item.Pointer);if(state.Gun.Template?.Pointer==state.Clone.Pointer)state.Gun._Template_k__BackingField=state.Original;}if(selected?.Pointer==item.Pointer)CloseAi();}
 internal static void Reset(){foreach(var state in owned.Values.ToArray())try{RestoreMods(state.Gun.Pointer);if(state.Gun.Template.Pointer==state.Clone.Pointer)state.Gun._Template_k__BackingField=state.Original;}catch{}owned.Clear();foreach(var value in shared.Values)try{Define(value.Template);foreach(var field in fields)Set(value.Template,field,Get(value.Original,field));}catch{}shared.Clear();selected=null;selectedId="";worldPointer=factoryPointer=IntPtr.Zero;aiActor=null;}
 internal static void DrawAi(Rect rect){if(InterfaceMenu.Button(new Rect(rect.x,rect.y,126,32),"返回装备")){CloseAi();return;}InterfaceMenu.Label(new Rect(rect.x+144,rect.y,rect.width-144,32),(aiActor?.Name??"AI")+" · 武器参数",InterfaceMenu.Accent,18);DrawCore(new Rect(rect.x,rect.y+48,rect.width,rect.height-48),true);}
 internal static void Draw(Rect rect)=>DrawCore(rect,false);
 static void DrawCore(Rect rect,bool ai){if(!ai&&aiActor!=null)CloseAi();Load();float x=rect.x,y=rect.y,w=rect.width;float cell=w/names.Length;if(!ai)for(int i=0;i<names.Length;i++)if(InterfaceMenu.Button(new Rect(x+i*cell,y,cell-6,32),names[i],tab==i)){tab=i;if(i<4)editTab=i;if(i<3){var gun=PreviewOwner()?.Profile?.Inventory?.Equipment?.GetSlot(slots[i])?.ContainedItem?.TryCast<Weapon>();if(gun!=null)Action(()=>Read(gun));else{selected=null;notice="该武器槽为空，进入战局后读取。";}}scroll=Vector2.zero;}if(ai){if(InterfaceMenu.Button(new Rect(x,y,(w-10)/2,32),"参数编辑",tab!=4))tab=editTab;if(InterfaceMenu.Button(new Rect(x+(w+10)/2,y,(w-10)/2,32),"参数方案",tab==4))tab=4;}y+=44;
  if(tab==4){var view=new Rect(x,y,w,Math.Max(70,rect.yMax-y-64));presetScroll=GUI.BeginScrollView(view,presetScroll,new Rect(0,0,w-20,presets.Count*74));WeaponTuningPreset? remove=null;for(int i=0;i<presets.Count;i++){var preset=presets[i];InterfaceMenu.Paragraph(new Rect(8,i*74,w-220,64),preset.Name+"\n"+ItemSpawner.TemplateName(preset.Template)+" · "+preset.Values.Count+" 个参数",null,12);if(InterfaceMenu.Button(new Rect(w-200,i*74+12,82,32),"载入"))Action(()=>Use(preset));if(InterfaceMenu.Button(new Rect(w-110,i*74+12,82,32),"删除"))remove=preset;}GUI.EndScrollView();if(remove!=null)Action(()=>{var next=presets.Where(p=>p.Id!=remove.Id).ToList();PresetStorage.Save(FilePath,next);presets.Clear();presets.AddRange(next);});InterfaceMenu.Paragraph(new Rect(x,rect.yMax-58,w,54),notice,InterfaceMenu.Accent,12);return;}
  if(tab==3){query=InterfaceMenu.Field(new Rect(x,y,w*.48f,28),query);if(lastQuery!=query){lastQuery=query;templates.Clear();templates.AddRange(ItemSpawner.FindEquipment(query,weaponParents,none));}var picker=new Rect(x,y+38,w*.48f,140);templateScroll=GUI.BeginScrollView(picker,templateScroll,new Rect(0,0,picker.width-20,templates.Count*35));int first=Math.Max(0,(int)(templateScroll.y/35)),end=Math.Min(templates.Count,first+6);for(int i=first;i<end;i++){var candidate=templates[i];if(InterfaceMenu.Button(new Rect(0,i*35,picker.width-24,30),candidate.Name))Action(()=>{var factory=Singleton<ItemFactory>.Instance??throw new ArgumentException("请进入战局后读取模板。");var gun=factory.CreateItem(factory.NextId.ToString(),candidate.Id,null)?.TryCast<Weapon>()??throw new ArgumentException("模板不是武器。");Read(gun);scopeTemplate=true;});}GUI.EndScrollView();InterfaceMenu.Paragraph(new Rect(x+w*.51f,y,w*.49f,170),"模板修改作用于本战局所有共用此型号模板的枪械；AI 的同型号枪械也会受影响。参数方案另存为后可在以后载入。",null,12);y+=188;}
  if(selected==null&&tab<3){var gun=PreviewOwner()?.Profile?.Inventory?.Equipment?.GetSlot(ai?aiSlot:slots[tab])?.ContainedItem?.TryCast<Weapon>();if(gun!=null)Action(()=>Read(gun));}
  if(selected==null){InterfaceMenu.Paragraph(new Rect(x,y,w,80),"进入战局后读取当前主武器、副武器或手枪；也可先浏览武器模板。",null,13);return;}
  InterfaceMenu.Label(new Rect(x,y,w-140,28),LootDisplay.ItemName(selected,false),InterfaceMenu.Accent,16);if(InterfaceMenu.Button(new Rect(x+w-130,y,130,28),"重新读取当前数值"))Action(()=>Read(selected));y+=37;if(!ai&&tab!=3&&InterfaceMenu.Button(new Rect(x,y,w,30),scopeTemplate?"修改范围：本战局同型号模板（包括 AI）":"修改范围：仅当前这把枪"))scopeTemplate=!scopeTemplate;y+=39;bool canIgnore=tab!=3&&!scopeTemplate;if(!canIgnore)ignoreAttachments=false;var oldEnabled=GUI.enabled;GUI.enabled=oldEnabled&&canIgnore;if(InterfaceMenu.Button(new Rect(x,y,w,30),ignoreAttachments?"忽略配件数值影响：开启（后座／工效／精度／初速）":"忽略配件数值影响：关闭",ignoreAttachments))ignoreAttachments=!ignoreAttachments;GUI.enabled=oldEnabled;y+=40;
  float footer=150;var area=new Rect(x,y,w,Math.Max(80,rect.yMax-y-footer));scroll=GUI.BeginScrollView(area,scroll,new Rect(0,0,w-20,fields.Count*40+122));for(int i=0;i<fields.Count;i++){var field=fields[i];bool active=enabled.Contains(field.Path);if(InterfaceMenu.Button(new Rect(0,i*40,Math.Max(100,(w-32)*.63f),32),(active?"✓ ":"＋ ")+field.Name,active)){if(!enabled.Remove(field.Path))enabled.Add(field.Path);}drafts[field.Path]=InterfaceMenu.Field(new Rect((w-32)*.65f,i*40,(w-32)*.35f,32),drafts.GetValueOrDefault(field.Path,"0"));}float conditionY=fields.Count*40+8;InterfaceMenu.Label(new Rect(0,conditionY,w-24,24),"当前这把枪的耐久（独立于模板出厂值）",null,12);durability=InterfaceMenu.Field(new Rect(0,conditionY+32,110,30),durability);maxDurability=InterfaceMenu.Field(new Rect(120,conditionY+32,110,30),maxDurability);if(InterfaceMenu.Button(new Rect(240,conditionY+32,Math.Max(90,w-270),30),"应用当前／最大耐久"))Action(Condition);GUI.EndScrollView();
  float bottom=rect.yMax-footer+8;float third=(w-16)/3;if(InterfaceMenu.Button(new Rect(x,bottom,third,32),"应用勾选数值"))Action(Apply);if(InterfaceMenu.Button(new Rect(x+third+8,bottom,third,32),"恢复原值"))Action(RestoreSelected);if(InterfaceMenu.Button(new Rect(x+2*(third+8),bottom,third,32),"查看当前数值"))Action(()=>readback=Final(Require()));bottom+=40;presetName=InterfaceMenu.Field(new Rect(x,bottom,Math.Max(100,w-212),30),presetName);if(InterfaceMenu.Button(new Rect(x+w-200,bottom,92,30),"保存方案"))Action(()=>Save(false));if(InterfaceMenu.Button(new Rect(x+w-100,bottom,100,30),"另存为"))Action(()=>Save(true));bottom+=38;InterfaceMenu.Paragraph(new Rect(x,bottom,w,58),notice+"\n"+readback+(RecoilAssist.Enabled.Value?"\n当前无后座已开启，会覆盖实际后座表现。":""),InterfaceMenu.Accent,11);
 }
